contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount, "insufficient test contract balance");
        require(c.owner() == address(this), "test contract is not the owner");

        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        bool reverted = false;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            (beforeC >= amount && !reverted && address(c).balance == beforeC - amount && address(this).balance == beforeThis + amount)
            ||
            (beforeC < amount && reverted && address(c).balance == beforeC && address(this).balance == beforeThis)
        );
    }

    receive() external payable {}
}

